 "content": "def transform(grid):
    # Recolor 1-valued objects that have the same shape as the 8-valued reference object.
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            todo = [(r, c)]
            seen.add((r, c))
            cells = []
            while todo:
                y, x = todo.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == color and (ny,nx) not in seen:
                        seen.add((ny,nx)); todo.append((ny,nx))
            comps.append((color, cells))
    refs = [cells for color, cells in comps if color == 8]
    if not refs:
        return [row[:] for row in grid]
    def shape(cells):
        my, mx = min(y for y,x in cells), min(x for y,x in cells)
        return frozenset((y-my,x-mx) for y,x in cells)
    ref_shapes = {shape(c) for c in refs}
    out = [row[:] for row in grid]
    for color, cells in comps:
        if color == 1 and shape(cells) in ref_shapes:
            for y,x in cells:
                out[y][x] = 8
    return out

if __name__ == '__main__':
